<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';import {useRoute} from 'vue-router';import {useAccount} from '../stores/account';import {useOnboarding} from '../stores/onboarding';import {safeReturnPath} from '../account/rules';import {botanicalAssets} from '../ui/botanical';import UiIcon from './UiIcon.vue';import CommandSearch from './CommandSearch.vue';import ResearchGuide from './ResearchGuide.vue'
const account=useAccount(),guide=useOnboarding(),route=useRoute(),menu=ref(false)
const workspace=computed(()=>['knowledge-graph','workbench','assistant','review'].includes(String(route.name)))
const destination=computed(()=>['login','register'].includes(String(route.name))?safeReturnPath(route.query.redirect):route.fullPath)
watch(()=>route.fullPath,()=>menu.value=false);onMounted(()=>{void account.refresh()})
const navigation=[['/explore','植物画廊'],['/knowledge-graph','漫游关系'],['/assistant','问问植序'],['/workbench','深入研究'],['/technology','幕后技术']]
</script>
<template><div class="app-shell" :class="{'is-workspace':workspace,'is-museum-home':route.name==='home'}"><a class="skip-link" href="#main-content">跳到主要内容</a><header class="app-header" @keydown.esc="menu=false"><RouterLink class="app-brand" to="/" aria-label="VIRIDEXA 植序首页"><span class="app-brand-symbol"><UiIcon name="leaf" :size="24"/></span><span>VIRIDEXA<span class="brand-zh">植序</span><small>BOTANICAL ATLAS</small></span></RouterLink><nav id="app-navigation" class="app-navigation" :class="{'is-open':menu}" aria-label="主要导航"><RouterLink v-for="[to,label] in navigation" :key="to" :to="to">{{label}}</RouterLink><RouterLink v-if="account.isAdmin" to="/review">审核台</RouterLink></nav><div class="app-header-tools"><CommandSearch/><button class="vx-icon-button guide-trigger" aria-label="打开新手指南" @click="guide.begin"><UiIcon name="book" :size="19"/></button><RouterLink class="app-account" :aria-label="account.profile?'我的账户：'+account.profile.displayName:'登录或注册公众账户'" :to="account.profile?'/account':{path:'/login',query:{redirect:destination}}"><UiIcon name="user" :size="17"/><span>{{account.profile?'我的空间':'登录 / 注册'}}</span></RouterLink><button class="vx-icon-button mobile-nav-toggle" aria-label="展开主导航" :aria-expanded="menu" aria-controls="app-navigation" @click="menu=!menu"><UiIcon :name="menu?'close':'menu'"/></button></div></header><div id="main-content" class="app-main" tabindex="-1"><slot/></div><ResearchGuide/><footer class="app-footer" :class="{'is-compact':workspace}"><div class="footer-mission"><RouterLink class="app-brand" to="/"><span class="app-brand-symbol"><UiIcon name="leaf"/></span><span>VIRIDEXA<small>植序 · BOTANICAL INTELLIGENCE</small></span></RouterLink><p>每一片叶子，都藏着一个世界。<br/>每一份发现，都能回到它的来源。</p></div><nav aria-label="页脚导航"><RouterLink to="/explore">浏览图鉴</RouterLink><RouterLink to="/knowledge-graph">探索关系</RouterLink><RouterLink to="/technology">幕后技术</RouterLink><button @click="guide.begin">新手指南</button></nav><div class="footer-note"><span>DESIGNED FOR CURIOSITY.</span><p>来源可浏览，审核独立。图像仅作图鉴插图。</p><details><summary>图片来源与许可</summary><a v-for="a in botanicalAssets" :key="a.species" :href="a.url" target="_blank" rel="noopener noreferrer">{{a.species}} · {{a.credit}} · {{a.license}}</a></details></div><div class="footer-baseline"><span>VIRIDEXA / Java Web 课程设计</span><span>Vue · Spring Boot · Evidence Lineage</span></div></footer></div></template>
